WITH supplier_totals AS (SELECT supplier_id, SUM(CASE WHEN brand = 'Stark' THEN 1 ELSE 0 END) stark_count FROM products WHERE category IN ('Electronics', 'Books', 'Home') GROUP BY supplier_id) SELECT suppliers.id, suppliers.country, suppliers.rating, supplier_totals.stark_count FROM suppliers INNER JOIN supplier_totals ON suppliers.id = supplier_totals.supplier_id WHERE supplier_totals.stark_count >= 78
